func publicParity_Decimal128BID_CompareTotal(t *testing.T) int {
	count := 0
	for _, pair := range publicParityBinaryPairs128 {
		av := publicParityCorpus128[pair[0]]
		bv := publicParityCorpus128[pair[1]]
		a := Decimal128BID(av)
		b := Decimal128BID(bv)
		pv := a.CompareTotal(b)
		fwd := bidgo.Bid128TotalOrder(publicParityToBidgo128(av), publicParityToBidgo128(bv))
		rev := bidgo.Bid128TotalOrder(publicParityToBidgo128(bv), publicParityToBidgo128(av))
		var want int
		switch {
		case fwd != 0 && rev != 0:
			want = 0
		case fwd != 0:
			want = -1
		default:
			want = 1
		}
		if pv != want {
			t.Errorf("public parity Decimal128BID.CompareTotal: operands %#x,%#x: result mismatch public=%v port=%v", av, bv, pv, want)
		}
		count++
	}
	return count
}

