func publicParity_Decimal128BID_ConvertToInt16(t *testing.T) int {
	count := 0
	for _, elem := range publicParityCorpus128 {
		a := Decimal128BID(elem)
		for _, mode := range publicParityModes {
			pv, pf := a.ConvertToInt16(mode.pub)
			var pr int16
			var prf uint32
			switch mode.pub {
			case RoundNearestEven:
				pr, prf = bidgo.Bid128ToInt16Rnint(publicParityToBidgo128(elem))
			case RoundNearestAway:
				pr, prf = bidgo.Bid128ToInt16Rninta(publicParityToBidgo128(elem))
			case RoundTowardZero:
				pr, prf = bidgo.Bid128ToInt16Int(publicParityToBidgo128(elem))
			case RoundTowardPositive:
				pr, prf = bidgo.Bid128ToInt16Ceil(publicParityToBidgo128(elem))
			case RoundTowardNegative:
				pr, prf = bidgo.Bid128ToInt16Floor(publicParityToBidgo128(elem))
			}
			if int64(pv) != int64(pr) {
				t.Errorf("public parity Decimal128BID.ConvertToInt16: operand %#x mode %v: result mismatch public=%v port=%v", elem, mode.pub, int64(pv), int64(pr))
			}
			if pf != mapPortFlagsForParity(prf) {
				t.Errorf("public parity Decimal128BID.ConvertToInt16: operand %#x mode %v: flag mismatch public=%v port=%v", elem, mode.pub, pf, mapPortFlagsForParity(prf))
			}
			count++
		}
	}
	invalidOperand := Decimal128BID(publicParityCorpus128[publicParityBinaryPairs128[0][0]])
	controlValue, controlFlags := invalidOperand.ConvertToInt16(publicParityModes[0].pub)
	if int64(controlValue) == -32768 && controlFlags == FlagInvalidOperation {
		t.Errorf("public parity Decimal128BID.ConvertToInt16: invalid-mode leg is vacuous: valid-mode result=%v flags=%v already equals the rejection value, so a dropped rejection would pass", int64(controlValue), controlFlags)
	}
	invalidValue, invalidFlags := invalidOperand.ConvertToInt16(RoundingMode(99))
	if int64(invalidValue) != -32768 || invalidFlags != FlagInvalidOperation {
		t.Errorf("public parity Decimal128BID.ConvertToInt16: invalid rounding mode result=%v flags=%v, want the NaN-conversion sentinel -32768 and FlagInvalidOperation", int64(invalidValue), invalidFlags)
	}
	count++
	return count
}

