func publicParity_Decimal128BID_MulWithMode(t *testing.T) int {
	count := 0
	for _, pair := range publicParityBinaryPairs128 {
		av := publicParityCorpus128[pair[0]]
		bv := publicParityCorpus128[pair[1]]
		a := Decimal128BID(av)
		b := Decimal128BID(bv)
		for _, mode := range publicParityModes {
			pv, pf := a.MulWithMode(b, mode.pub)
			pr, prf := bidgo.Bid128Mul(publicParityToBidgo128(av), publicParityToBidgo128(bv), mode.port)
			if pv.ToBytes() != publicParityFromBidgo128(pr) {
				t.Errorf("public parity Decimal128BID.MulWithMode: operands %#x,%#x mode %v: result mismatch public=%v port=%v", av, bv, mode.pub, pv.ToBytes(), publicParityFromBidgo128(pr))
			}
			if pf != mapPortFlagsForParity(prf) {
				t.Errorf("public parity Decimal128BID.MulWithMode: operands %#x,%#x mode %v: flag mismatch public=%v port=%v", av, bv, mode.pub, pf, mapPortFlagsForParity(prf))
			}
			count++
		}
	}
	discPairs := [][2][16]byte{
		{{0xff, 0xff, 0x63, 0xa7, 0xb3, 0xb6, 0xe0, 0x0d, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}, {0xff, 0xff, 0x89, 0x5d, 0x78, 0x45, 0x63, 0x01, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}},
		{{0xff, 0xff, 0xe7, 0x89, 0x04, 0x23, 0xc7, 0x8a, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}, {0xff, 0xff, 0xe7, 0x89, 0x04, 0x23, 0xc7, 0x8a, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}},
		{{0x55, 0x55, 0x4d, 0x83, 0x01, 0x61, 0x42, 0x2e, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}, {0x55, 0x55, 0x4d, 0x83, 0x01, 0x61, 0x42, 0x2e, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}},
		{{0x15, 0x81, 0xe9, 0x7d, 0xf4, 0x10, 0x22, 0x11, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}, {0xb1, 0x0c, 0xb7, 0xe3, 0xb8, 0x87, 0x10, 0x89, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}},
	}
	for _, dp := range discPairs {
		a := Decimal128BID(dp[0])
		b := Decimal128BID(dp[1])
		var modeSeen [5][16]byte
		for mi, mode := range publicParityModes {
			pv, pf := a.MulWithMode(b, mode.pub)
			pr, prf := bidgo.Bid128Mul(publicParityToBidgo128(dp[0]), publicParityToBidgo128(dp[1]), mode.port)
			if pv.ToBytes() != publicParityFromBidgo128(pr) {
				t.Errorf("public parity Decimal128BID.MulWithMode: discriminant operands %#x,%#x mode %v: result mismatch public=%v port=%v", dp[0], dp[1], mode.pub, pv.ToBytes(), publicParityFromBidgo128(pr))
			}
			if pf != mapPortFlagsForParity(prf) {
				t.Errorf("public parity Decimal128BID.MulWithMode: discriminant operands %#x,%#x mode %v: flag mismatch public=%v port=%v", dp[0], dp[1], mode.pub, pf, mapPortFlagsForParity(prf))
			}
			modeSeen[mi] = pv.ToBytes()
			count++
		}
		modeInsensitive := true
		for mi := 1; mi < len(modeSeen); mi++ {
			if modeSeen[mi] != modeSeen[0] {
				modeInsensitive = false
				break
			}
		}
		if modeInsensitive {
			t.Errorf("public parity Decimal128BID.MulWithMode: discriminant operands %#x,%#x: every rounding mode produced the same result; the mode-discriminant corpus entry no longer discriminates", dp[0], dp[1])
		}
	}
	invalidLeft := Decimal128BID(publicParityCorpus128[publicParityBinaryPairs128[0][0]])
	invalidRight := Decimal128BID(publicParityCorpus128[publicParityBinaryPairs128[0][1]])
	controlValue, controlFlags := invalidLeft.MulWithMode(invalidRight, publicParityModes[0].pub)
	if controlValue.ToBytes() == ([16]byte{15: 0x7c}) && controlFlags == FlagInvalidOperation {
		t.Errorf("public parity Decimal128BID.MulWithMode: invalid-mode leg is vacuous: valid-mode result=%v flags=%v already equals the rejection value, so a dropped rejection would pass", controlValue.ToBytes(), controlFlags)
	}
	invalidValue, invalidFlags := invalidLeft.MulWithMode(invalidRight, RoundingMode(99))
	if invalidValue.ToBytes() != ([16]byte{15: 0x7c}) || invalidFlags != FlagInvalidOperation {
		t.Errorf("public parity Decimal128BID.MulWithMode: invalid rounding mode result=%v flags=%v, want canonical qNaN and FlagInvalidOperation", invalidValue.ToBytes(), invalidFlags)
	}
	count++
	return count
}

