func publicParity_Decimal128BID_ScaleBWithMode(t *testing.T) int {
	count := 0
	for _, elem := range publicParityCorpus128 {
		a := Decimal128BID(elem)
		for _, exp := range publicParityScaleBExps {
			for _, mode := range publicParityModes {
				pv, pf := a.ScaleBWithMode(exp, mode.pub)
				var prf uint32
				pr := bidgo.Bid128Scalbln(publicParityToBidgo128(elem), int64(exp), mode.port, &prf)
				if pv.ToBytes() != publicParityFromBidgo128(pr) {
					t.Errorf("public parity Decimal128BID.ScaleBWithMode: operand %#x exp %d mode %v: result mismatch public=%v port=%v", elem, exp, mode.pub, pv.ToBytes(), publicParityFromBidgo128(pr))
				}
				if pf != mapPortFlagsForParity(prf) {
					t.Errorf("public parity Decimal128BID.ScaleBWithMode: operand %#x exp %d mode %v: flag mismatch public=%v port=%v", elem, exp, mode.pub, pf, mapPortFlagsForParity(prf))
				}
				count++
			}
		}
	}
	discCases := []struct {
		v   [16]byte
		exp int
	}{
		{[16]byte{0x15, 0x81, 0xe9, 0x7d, 0xf4, 0x10, 0x22, 0x11, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}, 6127},
		{[16]byte{0x15, 0x81, 0xe9, 0x7d, 0xf4, 0x10, 0x22, 0x11, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0xb0}, 6127},
		{[16]byte{0x15, 0x81, 0xe9, 0x7d, 0xf4, 0x10, 0x22, 0x11, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x40, 0x30}, -6195},
		{[16]byte{0x05, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x3e, 0x30}, -6176},
	}
	for _, dc := range discCases {
		a := Decimal128BID(dc.v)
		var modeSeen [5][16]byte
		for mi, mode := range publicParityModes {
			pv, pf := a.ScaleBWithMode(dc.exp, mode.pub)
			var prf uint32
			pr := bidgo.Bid128Scalbln(publicParityToBidgo128(dc.v), int64(dc.exp), mode.port, &prf)
			if pv.ToBytes() != publicParityFromBidgo128(pr) {
				t.Errorf("public parity Decimal128BID.ScaleBWithMode: discriminant operand %#x exp %d mode %v: result mismatch public=%v port=%v", dc.v, dc.exp, mode.pub, pv.ToBytes(), publicParityFromBidgo128(pr))
			}
			if pf != mapPortFlagsForParity(prf) {
				t.Errorf("public parity Decimal128BID.ScaleBWithMode: discriminant operand %#x exp %d mode %v: flag mismatch public=%v port=%v", dc.v, dc.exp, mode.pub, pf, mapPortFlagsForParity(prf))
			}
			modeSeen[mi] = pv.ToBytes()
			count++
		}
		modeInsensitive := true
		for mi := 1; mi < len(modeSeen); mi++ {
			if modeSeen[mi] != modeSeen[0] {
				modeInsensitive = false
				break
			}
		}
		if modeInsensitive {
			t.Errorf("public parity Decimal128BID.ScaleBWithMode: discriminant operand %#x exp %d: every rounding mode produced the same result; the mode-discriminant corpus entry no longer discriminates", dc.v, dc.exp)
		}
	}
	invalidOperand := Decimal128BID(publicParityCorpus128[publicParityBinaryPairs128[0][0]])
	controlValue, controlFlags := invalidOperand.ScaleBWithMode(publicParityScaleBExps[0], publicParityModes[0].pub)
	if controlValue.ToBytes() == ([16]byte{15: 0x7c}) && controlFlags == FlagInvalidOperation {
		t.Errorf("public parity Decimal128BID.ScaleBWithMode: invalid-mode leg is vacuous: valid-mode result=%v flags=%v already equals the rejection value, so a dropped rejection would pass", controlValue.ToBytes(), controlFlags)
	}
	invalidValue, invalidFlags := invalidOperand.ScaleBWithMode(publicParityScaleBExps[0], RoundingMode(99))
	if invalidValue.ToBytes() != ([16]byte{15: 0x7c}) || invalidFlags != FlagInvalidOperation {
		t.Errorf("public parity Decimal128BID.ScaleBWithMode: invalid rounding mode result=%v flags=%v, want canonical qNaN and FlagInvalidOperation", invalidValue.ToBytes(), invalidFlags)
	}
	count++
	return count
}

func publicParity_Decimal128BID_Sign(t *testing.T) int {
	count := 0
	for _, elem := range publicParityCorpus128 {
		a := Decimal128BID(elem)
		pv := a.Sign()
		var want int
		switch {
		case bidgo.Bid128IsZero(publicParityToBidgo128(elem)) != 0:
			want = 0
		case bidgo.Bid128IsSigned(publicParityToBidgo128(elem)) != 0:
			want = -1
		default:
			want = 1
		}
		if pv != want {
			t.Errorf("public parity Decimal128BID.Sign: operand %#x: result mismatch public=%v port=%v", elem, pv, want)
		}
		count++
	}
	return count
}

