		bv := publicParityCorpus128[pair[1]]
		a := Decimal128BID(av)
		b := Decimal128BID(bv)
		pv, pf := a.SignalingEqual(b)
		ge, geF := bidgo.Bid128SignalingGreaterEqual(publicParityToBidgo128(av), publicParityToBidgo128(bv))
