func publicParity_Decimal64BID_CompareTotal(t *testing.T) int {
	count := 0
	for _, pair := range publicParityBinaryPairs64 {
		av := publicParityCorpus64[pair[0]]
		bv := publicParityCorpus64[pair[1]]
		a := Decimal64BID(av)
		b := Decimal64BID(bv)
		pv := a.CompareTotal(b)
		fwd := bidgo.Bid64TotalOrder(av, bv)
		rev := bidgo.Bid64TotalOrder(bv, av)
		var want int
		switch {
		case fwd != 0 && rev != 0:
			want = 0
		case fwd != 0:
			want = -1
		default:
			want = 1
		}
		if pv != want {
			t.Errorf("public parity Decimal64BID.CompareTotal: operands %#x,%#x: result mismatch public=%v port=%v", av, bv, pv, want)
		}
		count++
	}
	return count
}

