func publicParity_NewDecimal128(t *testing.T) int {
	count := 0
	for _, sc := range publicParityStringCases {
		pv, err := NewDecimal128(sc.input)
		switch sc.kind {
		case "blank", "invalid_syntax":
			if err == nil {
				t.Errorf("public parity NewDecimal128: input %q: rejected input kind %s must error", sc.input, sc.kind)
			}
			if pv != (Decimal128BID{}) {
				t.Errorf("public parity NewDecimal128: input %q: error result bits = %x, want zero", sc.input, pv.ToBytes())
			}
		case "nan_literal":
			if sc.nanMinWidth == 0 || sc.nanMinWidth > 128 {
				if err == nil {
					t.Errorf("public parity NewDecimal128: input %q: unrepresentable NaN payload must error", sc.input)
				}
				if pv != (Decimal128BID{}) {
					t.Errorf("public parity NewDecimal128: input %q: error result bits = %x, want zero", sc.input, pv.ToBytes())
				}
			} else {
				if err != nil {
					t.Errorf("public parity NewDecimal128: input %q: unexpected error %v", sc.input, err)
				} else {
					if !(bidgo.Bid128IsNaN(publicParityToBidgo128(pv.ToBytes())) != 0) {
						t.Errorf("public parity NewDecimal128: input %q: expected a NaN result from the NaN literal branch", sc.input)
					}
					if (bidgo.Bid128IsSignaling(publicParityToBidgo128(pv.ToBytes())) != 0) != sc.signaling {
						t.Errorf("public parity NewDecimal128: input %q: signaling bit mismatch public=%v literal=%v", sc.input, bidgo.Bid128IsSignaling(publicParityToBidgo128(pv.ToBytes())) != 0, sc.signaling)
					}
				}
			}
		default:
			pr, prf := bidgo.Bid128FromString(sc.input, 0)
			portFlags := mapPortFlagsForParity(prf)
			silentCohortCoercion := sc.kind == "cohort_coercion" && (sc.cohortMinWidth == 0 || sc.cohortMinWidth > 128) && prf == 0
			shouldError := (bidgo.Bid128IsNaN(pr) != 0) || silentCohortCoercion
			shouldError = shouldError || portFlags&(FlagInvalidOperation|FlagOverflow|FlagUnderflow|FlagInexact) != 0
			switch {
			case shouldError:
				if err == nil {
					t.Errorf("public parity NewDecimal128: input %q: expected an error for a NaN or unrepresentable port result", sc.input)
				}
				if pv != (Decimal128BID{}) {
					t.Errorf("public parity NewDecimal128: input %q: error result bits = %x, want zero", sc.input, pv.ToBytes())
				}
			case err != nil:
				t.Errorf("public parity NewDecimal128: input %q: unexpected error %v", sc.input, err)
			default:
				if pv.ToBytes() != publicParityFromBidgo128(pr) {
					t.Errorf("public parity NewDecimal128: input %q: result mismatch public=%v port=%v", sc.input, pv.ToBytes(), publicParityFromBidgo128(pr))
				}
			}
		}
		count++
	}
	return count
}

