func publicParity_NewDecimal128FromInt(t *testing.T) int {
	count := 0
	for _, x := range publicParityIntCorpus64 {
		pv, err := NewDecimal128FromInt(x)
		pr := bidgo.Bid128FromInt64(int64(x))
		shouldError := mapPortFlagsForParity(0)&FlagInexact != 0
		if shouldError {
			if err == nil {
				t.Errorf("public parity NewDecimal128FromInt: operand %v: expected exact-representation error, got %v", x, pv)
			}
			if !pv.IsNaN() {
				t.Errorf("public parity NewDecimal128FromInt: operand %v: error result must be NaN, got %v", x, pv)
			}
		} else {
			if err != nil {
				t.Errorf("public parity NewDecimal128FromInt: operand %v: unexpected error %v", x, err)
			}
			if pv.ToBytes() != publicParityFromBidgo128(pr) {
				t.Errorf("public parity NewDecimal128FromInt: operand %v: result mismatch public=%v port=%v", x, pv.ToBytes(), publicParityFromBidgo128(pr))
			}
		}
		count++
	}
	return count
}

